    --button-primary-default-left-border-color: var(
      --amis-Button-primary-border-color
    );
    --button-primary-default-right-border-color: var(
      --amis-Button-primary-border-color
    );
    --button-primary-default-bottom-border-color: var(
      --amis-Button-primary-border-color
    );
    --button-primary-default-bg-color: var(--amis-Button-primary-bg);
    --button-primary-hover-top-border-color: var(
      --amis-Button-primary-hover-border-color
    );
    --button-primary-hover-left-border-color: var(
      --amis-Button-primary-hover-border-color
    );
    --button-primary-hover-right-border-color: var(
      --amis-Button-primary-hover-border-color
    );
    --button-primary-hover-bottom-border-color: var(
      --amis-Button-primary-hover-border-color
    );
    --button-primary-hover-bg-color: var(--amis-Button-primary-hover-bg);
