  --fontSizeBase: var(--fonts-size-7);
  --fontSizeMd: var(--fonts-size-7);
  --fontSizeLg: var(--fonts-size-6);
  --fontSizeXl: var(--fonts-size-5);
  --fontSizeSm: var(--fonts-size-8);
  --fontSizeXs: var(--fonts-size-8);
